    TreeNode<T> rightNode = node.right;

    if (rightNode != null) {
        // Perform the right node rotation
        node.right = rightNode.left;

        // Update the height of the node and left subtree
        node.height = Math.max(node.height, rightNode.left.height + 1);

        // Update the height of the grandparent and right subtree
        rightNode.height = Math.max(rightNode.height, node.height + 1);

        // Update the parent of rightNode
        if (rightNode.left != null)
            rightNode.left.parent = node;
    }

    // Update the parent of node
    if (node.parent != null) {
        if (node.parent.left == node)
            node.parent.left = rightNode;
        else
            node.parent.right = rightNode;
    }

    // Update the parent of rightNode
    if (rightNode != null)
        rightNode.parent = node;

    return rightNode;
}

