    }

    int size = 0;
    while (len > 0) {
        int byte1 = (str.charAt(index++) & 0xff);
        if ((byte1 >> 7) == 0) {
            size++;
        } else if ((byte1 >> 5) == 0x6) {
            size += 2;
        } else if ((byte1 >> 4) == 0xE) {
            size += 3;
        } else if ((byte1 >> 3) == 0xF) {
            size += 4;
