private boolean unlink(ListNodeImpl<E> node) {
    // Singleton design pattern for a single instance of the head and tail
    if (head == tail) {
        head = tail = null;
        return true;
    }

    if (head == node) {
        ListNodeImpl<E> temp = head;
        head = head.next;
        temp.next = null;
        return true;
    }

    ListNodeImpl<E> current = head.next;
    while (current.next != null && current.next != node) {
        current = current.next;
    }

    if (current.next == node) {
        ListNodeImpl<E> temp = current.next;
        current.next = temp.next;
        temp.next = null;
        return true;
    }

    return false;
}

