    read = in.read();
    if (read != -1) {
        tag |= (read & 0x7F) << 7;
    }
    read = in.read();
    if (read != -1) {
        tag |= (read & 0x7F) << 14;
    }
    read = in.read();
    if (read != -1) {
        tag |= ((read & 0x7F) << 21) >>> 1;
    }
    return tag;
}

