public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        ProfileAnalyzeTimeRange currentRange = null;
        StringBuilder build = new StringBuilder();
        ProfileAnalyzeTimeRange totalTime ranges[] = timeRanges.toArray(new ProfileAnalyzeTimeRange[0]);

        while ((line = br.readLine()) != null) {
            // Assuming the line format is time:start:endId
            String[] parts = line.split(":");
            if (parts.length == 3) {
                currentRange = new ProfileAnalyzeTimeRange(Long.parseLong(parts[0]), Long.parseLong(parts[1]), parts[2].trim());
            }
            // When a line represents the start of a range,纪录下前面的数据库信息
            if (currentRange == null) {
                continue;
            }
            if (parts.length > 3) {

                currentRange.getEndId = parts[3];
                threadSnapshots.add(parsingBuild(line, build));
                build.replace(0, build.length(), "");
            }
        }
        //滤出不属于计算时间的模块
        threadSnapshots.removeIf(task -> Arrays.stream(totalRanges).mapToInt(ProfileAnalyzeTimeRange::getTime).max().orElse(0L) > task.getTime());
    }
    return threadSnapshots;
}

/**
 * This is a helper function to parse the current line and build the thread snapshot object
